CREATE OR REPLACE FUNCTION private.current_company_portal_id(p_require_active boolean DEFAULT true)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_company_id uuid; v_count integer;
begin
  if auth.uid() is null then return null; end if;
  select min(cu.company_id::text)::uuid, count(*)::integer into v_company_id, v_count
  from public.company_users cu join public.platform_users pu on pu.user_id=cu.user_id
    join public.companies c on c.id=cu.company_id
  where cu.user_id=auth.uid() and pu.account_type='company'
    and (not p_require_active or (pu.account_status='active' and cu.status='active' and c.account_status='active'));
  if v_count=0 then return null; end if;
  if v_count<>1 then raise exception 'Exactly one company membership is required'; end if;
  return v_company_id;
end;
$function$

CREATE OR REPLACE FUNCTION private.current_contractor_portal_id(p_require_active boolean DEFAULT true)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare resolved uuid; membership_count integer;
begin
  if (select auth.uid()) is null then return null; end if;
  select min(cu.contractor_id::text)::uuid,count(*)::integer into resolved,membership_count
  from public.contractor_users cu join public.platform_users pu on pu.user_id=cu.user_id
    join public.contractors c on c.id=cu.contractor_id
  where cu.user_id=(select auth.uid()) and pu.account_type='contractor'
    and (not p_require_active or (pu.account_status='active' and cu.status='active' and c.account_status='active'));
  if membership_count=0 then return null; end if;
  if membership_count<>1 then raise exception 'Exactly one contractor membership is required'; end if;
  return resolved;
end $function$

CREATE OR REPLACE FUNCTION private.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_list_candidate_documents(p_candidate_id uuid)
 RETURNS TABLE(document_id uuid, document_type text, display_file_name text, mime_type text, file_size_bytes bigint, verification_status text, verification_feedback text, uploaded_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not (select private.can_verify_candidate_documents()) then raise exception 'Candidate document verification access is required'; end if;
  return query select d.id,d.document_type,d.display_file_name,d.mime_type,d.file_size_bytes,
    d.verification_status,d.verification_feedback,d.uploaded_at from public.candidate_documents d
  where d.candidate_id=p_candidate_id and d.active order by d.document_type;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_review_candidate_document(p_document_id uuid, p_status text, p_feedback text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_status text:=lower(btrim(coalesce(p_status,'')));
  v_feedback text:=nullif(btrim(p_feedback),'');
  v_candidate uuid;
  v_prior text;
  v_actor uuid:=(select auth.uid());
  v_now timestamptz:=clock_timestamp();
  v_action text;
begin
  if not (select private.can_verify_candidate_documents()) then
    raise exception 'Candidate document verification access is required';
  end if;
  if v_status not in ('under_verification','verified','reupload_required')
     or length(coalesce(v_feedback,''))>1000
     or (v_status='reupload_required' and length(coalesce(v_feedback,''))<5)
     or (v_status in ('under_verification','verified') and v_feedback is not null) then
    raise exception 'Document review details are invalid';
  end if;

  select d.candidate_id,d.verification_status into v_candidate,v_prior
  from public.candidate_documents d where d.id=p_document_id and d.active for update;
  if v_candidate is null then raise exception 'Candidate document was not found'; end if;

  if v_status='under_verification' then
    if v_prior<>'uploaded' then raise exception 'Only an uploaded document can enter verification'; end if;
    update public.candidate_documents d set verification_status='under_verification',
      verification_feedback=null,review_started_at=v_now,review_started_by=v_actor,
      reviewed_at=null,reviewed_by=null,verified_at=null,verified_by=null
      where d.id=p_document_id;
    v_action:='candidate.document_review_started';
  elsif v_status='verified' then
    if v_prior<>'under_verification' then raise exception 'Only an under-verification document can be verified'; end if;
    update public.candidate_documents d set verification_status='verified',
      verification_feedback=null,reviewed_at=v_now,reviewed_by=v_actor,
      verified_at=v_now,verified_by=v_actor where d.id=p_document_id;
    v_action:='candidate.document_verified';
  else
    if v_prior<>'under_verification' then raise exception 'Only an under-verification document can require re-upload'; end if;
    update public.candidate_documents d set verification_status='reupload_required',
      verification_feedback=v_feedback,reviewed_at=v_now,reviewed_by=v_actor,
      verified_at=null,verified_by=null where d.id=p_document_id;
    v_action:='candidate.document_reupload_requested';
  end if;

  insert into public.audit_logs(actor_user_id,actor_type,action,entity_type,entity_id,source,metadata)
  values(v_actor,'staff',v_action,'candidate_document',p_document_id,'admin',jsonb_build_object('status',v_status));
  return true;
end;
$function$
